import type { Request, RequestHandler } from "express";

const DEFAULT_REQUESTS_PER_WINDOW = 60;
const DEFAULT_WINDOW_MS = 60_000;
const DEFAULT_BURST_CAPACITY = 20;

export interface RateLimiterOptions {
  maxRequests?: number;
  windowMs?: number;
  burstCapacity?: number;
  keyGenerator?: (req: Request) => string;
  now?: () => number;
}

interface Bucket {
  tokens: number;
  lastRefillAt: number;
}

function positiveNumber(value: string | undefined, fallback: number): number {
  const parsed = Number(value);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : fallback;
}

function defaultKeyGenerator(req: Request): string {
  return req.ip ?? "unknown";
}

export function createRateLimiter(options: RateLimiterOptions = {}): RequestHandler {
  const maxRequests = options.maxRequests ?? positiveNumber(
    process.env.RATE_LIMIT_REQUESTS_PER_WINDOW ?? process.env.RATE_LIMIT_REQUESTS_PER_MINUTE,
    DEFAULT_REQUESTS_PER_WINDOW,
  );
  const windowMs = options.windowMs ?? positiveNumber(process.env.RATE_LIMIT_WINDOW_MS, DEFAULT_WINDOW_MS);
  const burstCapacity = options.burstCapacity ?? positiveNumber(process.env.RATE_LIMIT_BURST, DEFAULT_BURST_CAPACITY);
  const keyGenerator = options.keyGenerator ?? defaultKeyGenerator;
  const now = options.now ?? Date.now;
  const refillRate = maxRequests / windowMs;
  const buckets = new Map<string, Bucket>();

  return (req, res, next) => {
    const currentTime = now();
    const key = keyGenerator(req);
    const existingBucket = buckets.get(key);
    const bucket = existingBucket ?? { tokens: burstCapacity, lastRefillAt: currentTime };

    if (existingBucket) {
      bucket.tokens = Math.min(
        burstCapacity,
        bucket.tokens + (currentTime - bucket.lastRefillAt) * refillRate,
      );
      bucket.lastRefillAt = currentTime;
    }

    if (bucket.tokens < 1) {
      const retryAfter = Math.max(1, Math.ceil((1 - bucket.tokens) / refillRate / 1000));
      res.setHeader("Retry-After", retryAfter.toString());
      res.status(429).json({ error: "Too many requests", retryAfter });
      return;
    }

    bucket.tokens -= 1;
    buckets.set(key, bucket);
    next();
  };
}

export const rateLimiter = createRateLimiter();


