import express from "express";
import request from "supertest";
import { describe, expect, it } from "vitest";
import { createRateLimiter } from "../src/middleware/rateLimiter.js";

function createTestApp(now: () => number) {
  const app = express();
  app.use(createRateLimiter({
    maxRequests: 2,
    windowMs: 1_000,
    burstCapacity: 2,
    keyGenerator: (req) => req.get("x-client-id") ?? "anonymous",
    now,
  }));
  app.get("/", (_req, res) => res.json({ status: "ok" }));
  return app;
}

describe("rate limiter", () => {
  it("enforces the configured limit", async () => {
    const app = createTestApp(() => 0);

    expect((await request(app).get("/").set("x-client-id", "client-a")).status).toBe(200);
    expect((await request(app).get("/").set("x-client-id", "client-a")).status).toBe(200);

    const limited = await request(app).get("/").set("x-client-id", "client-a");
    expect(limited.status).toBe(429);
    expect(limited.headers["retry-after"]).toBe("1");
    expect(limited.body).toEqual({ error: "Too many requests", retryAfter: 1 });
  });

  it("refills the bucket after the window", async () => {
    let currentTime = 0;
    const app = createTestApp(() => currentTime);

    await request(app).get("/").set("x-client-id", "client-a");
    await request(app).get("/").set("x-client-id", "client-a");
    expect((await request(app).get("/").set("x-client-id", "client-a")).status).toBe(429);

    currentTime = 1_000;
    expect((await request(app).get("/").set("x-client-id", "client-a")).status).toBe(200);
  });
});


